\centering
\small
\begin{tabular}{lccll}
\toprule
Estimator & $K$ & Max ratio & Worst config & Mechanism \\
\midrule
DIM & 2 & 2.86 & extr./sg0 & additive \\
DIM & 4 & 2.41 & extr./sg0 & distributed \\
